import React from 'react';
import manifest from '../data/image-dimensions.json';

/**
 * Renders a local JPEG image as a WebP source with a JPEG fallback, and — when
 * a responsive ladder has been generated for the file — as a `srcset` with
 * width descriptors.
 *
 * `picture` uses `display: contents` so the inner `img` keeps the exact
 * layout box the call site expects (grid, absolute positioning, h-full, ...).
 *
 * Widths come from src/data/image-dimensions.json, generated by
 * `npm run images`. `sizes` stays at the call site because only the call site
 * knows how wide the frame is; see the note on `sizes` below.
 */
export default function Picture({ src, alt = '', className = '', ...imgProps }) {
  const isJpeg = typeof src === 'string' && /\.jpe?g(\?.*)?$/i.test(src);
  const imgClass =
    `${className} outline outline-1 outline-black/10 [outline-offset:-1px] dark:outline-white/10`.trim();

  if (!isJpeg) {
    return <img src={src} alt={alt} className={imgClass} {...imgProps} />;
  }

  // A path may carry a BASE_URL prefix; the manifest is keyed by file name.
  const file = src.split('/').pop();
  const entry = manifest[file];
  const webp = (p) => p.replace(/\.jpe?g(\?.*)?$/i, '.webp$1');
  // Rung paths in the manifest are relative to the public root, so they need
  // the same prefix the call site used — which is how Vite's BASE_URL arrives.
  const dir = src.slice(0, src.lastIndexOf('/') + 1);
  const href = (p) => dir + p.replace(/^\/?images\//, '');

  // No generated ladder: degrade to the single full-size pair, exactly the
  // behaviour this component had before srcset existed.
  if (!entry) {
    return (
      <picture className="contents">
        <source srcSet={webp(src)} type="image/webp" />
        <img src={src} alt={alt} className={imgClass} {...imgProps} />
      </picture>
    );
  }

  const srcset = (key) => entry.sources.map((s) => `${href(s[key])} ${s.width}w`).join(', ');

  return (
    <picture className="contents">
      <source srcSet={srcset('webp')} sizes={imgProps.sizes} type="image/webp" />
      <img src={src} srcSet={srcset('jpg')} alt={alt} className={imgClass} {...imgProps} />
    </picture>
  );
}
